import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Relazione fra archi e corde","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/fj/fjd.md","filePath":"lezioni/f_geometria-del-piano-euclideo/fj/fjd.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/fj/fjd.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="relazione-fra-archi-e-corde" tabindex="-1">Relazione fra archi e corde <a class="header-anchor" href="#relazione-fra-archi-e-corde" aria-label="Permalink to “Relazione fra archi e corde”">​</a></h1><blockquote><p>Vediamo ora un teorema che di solito passa quasi sotto silenzio, ma che per la sua importanza andrebbe invece ben evidenziato: i suoi risultati permettono di costruire la goniometria permettendoci di misurare gli archi in gradi e gli angoli in centimetri (radianti).</p></blockquote><h2 id="teorema" tabindex="-1">Teorema <a class="header-anchor" href="#teorema" aria-label="Permalink to “Teorema”">​</a></h2><p><strong>In ogni circonferenza gli archi e gli angoli al centro che tali archi sottendono sono tra loro in proporzionalità diretta</strong></p><p>In proporzionalità diretta significa che si conservano l&#39;uguaglianza e la somma: in particolare significa:</p><ul><li><p>Se gli archi sono congruenti allora sono congruenti anche gli angoli al centro e viceversa. Esempio: Essendo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="blue"><mtext>AB</mtext></mstyle><mo>=</mo><mstyle mathcolor="blue"><mtext>CD</mtext></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{blue}{\\text{AB}} = \\textcolor{blue}{\\text{CD}}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text" style="color:blue;"><span class="mord" style="color:blue;">AB</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text" style="color:blue;"><span class="mord" style="color:blue;">CD</span></span></span></span></span>, segue <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="blue"><mi mathvariant="normal">∠</mi><mtext>AOB</mtext></mstyle><mo>=</mo><mstyle mathcolor="blue"><mi mathvariant="normal">∠</mi><mtext>COD</mtext></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{blue}{\\angle\\text{AOB}} = \\textcolor{blue}{\\angle\\text{COD}}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6922em;"></span><span class="mord" style="color:blue;">∠</span><span class="mord text" style="color:blue;"><span class="mord" style="color:blue;">AOB</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6922em;"></span><span class="mord" style="color:blue;">∠</span><span class="mord text" style="color:blue;"><span class="mord" style="color:blue;">COD</span></span></span></span></span> e viceversa.</p></li><li><p>Se un arco è doppio, triplo, quadruplo... di un altro, anche l&#39;angolo al centro corrispondente è doppio, triplo, quadruplo... dell&#39;angolo al centro corrispondente. Esempio: Essendo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="blue"><mtext>AB</mtext></mstyle><mo>=</mo><mn>2</mn><mstyle mathcolor="blue"><mtext>EF</mtext></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{blue}{\\text{AB}} = 2 \\textcolor{blue}{\\text{EF}}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text" style="color:blue;"><span class="mord" style="color:blue;">AB</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord">2</span><span class="mord text" style="color:blue;"><span class="mord" style="color:blue;">EF</span></span></span></span></span>, segue che <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="blue"><mi mathvariant="normal">∠</mi><mtext>AOB</mtext></mstyle><mo>=</mo><mn>2</mn><mstyle mathcolor="blue"><mi mathvariant="normal">∠</mi><mtext>EOF</mtext></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{blue}{\\angle\\text{AOB}} = 2 \\textcolor{blue}{\\angle\\text{EOF}}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6922em;"></span><span class="mord" style="color:blue;">∠</span><span class="mord text" style="color:blue;"><span class="mord" style="color:blue;">AOB</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6922em;"></span><span class="mord">2</span><span class="mord" style="color:blue;">∠</span><span class="mord text" style="color:blue;"><span class="mord" style="color:blue;">EOF</span></span></span></span></span></p></li></ul><blockquote><p>Se due insiemi di enti sono tra loro direttamente proporzionali allora le proprietà che valgono per il primo insieme valgono anche per il secondo.</p></blockquote>`,7)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};